using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Model
{
    // BUSINESS LAYER: Model.
    // Represents one row of TabBorrow, which is one loan of one book to one user.
    //
    //     TabBorrow
    //       BID               int       -> primary key, generated by the database
    //       UID               int       -> FK to TabUser
    //       ISBN              varchar   -> FK to TabBook
    //       BorrowDate        date
    //       ReturnDate        date      -> the date the book is DUE
    //       ActualReturnDate  date      -> when it really came back
    //       LateFee           decimal
    //
    // A book that has not been returned yet still needs a date in ActualReturnDate,
    // because the column does not accept nulls. The system stores 1/1/2000 there and
    // treats that as "still out", which is the rule given in the brief.
    public class Borrow
    {
        private int bId;
        private int uId;
        private string isbn;
        private DateTime borrowDate;
        private DateTime returnDate;
        private DateTime actualReturnDate;
        private decimal lateFee;

        // Not a column in TabBorrow. BorrowLogic fills it in from the book list so the
        // return drop-down can show the title instead of just an ISBN.
        private string bookName;

        public int BID { get => bId; set => bId = value; }
        public int UID { get => uId; set => uId = value; }
        public string ISBN { get => isbn; set => isbn = value; }
        public DateTime BorrowDate { get => borrowDate; set => borrowDate = value; }
        public DateTime ReturnDate { get => returnDate; set => returnDate = value; }
        public DateTime ActualReturnDate { get => actualReturnDate; set => actualReturnDate = value; }
        public decimal LateFee { get => lateFee; set => lateFee = value; }
        public string BookName { get => bookName; set => bookName = value; }

        // A ComboBox shows whatever ToString() returns, so this is what the student
        // reads when choosing which book to return.
        public override string ToString()
        {
            return bookName + "  (due " + returnDate.ToShortDateString() + ")";
        }
    }
}